<form class="date-filter compact-date-filter" wire:submit="filter"><label for="date-from">From<x-input id="date-from" type="date" wire:model="from" /></label><label for="date-to">To<x-input id="date-to" type="date" wire:model="to" /></label><div class="date-actions"><button class="btn btn-sage btn-sm" type="submit" aria-label="Apply date range">Apply</button><button class="btn btn-light btn-sm" type="button" wire:click="clearDates">Clear</button>@if($withReset??false)<button class="btn btn-light btn-sm" type="button" wire:click="resetFilters">Reset filters</button>@endif</div></form>
